from builtins import range
from builtins import object
import getpass
import os
import re
import time
import paramiko
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.oam.admin.commissioning import Commissioning
from ute_common_store.store import Store
from paramiko import RSAKey
from scp import SCPClient
from taf.ul.trs_e2e_fw.lib.utils.exception.robot_exception import SSHException
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str

logger = BackgroundLogger.Instance()


class SshController(object):
    store = Store()

    def __init__(self):
        self.root_error_list = ['Permission denied', 'command not found']
        pass

    def establish_ssh_connection_with_host(self, host_details, timeout, alias):
        """
        Creates a session with the host, specified by host_details
        @param host_details: dict, connection details to the host
        @param timeout: int, execution timeout.
        @param alias: string, Execution context
        @return:
        @raise SSHException: raises an exception
        """
        ssh_client = paramiko.SSHClient()
        ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        self._connect(ssh_client, alias, host_details)
        host_details["session_object"] = ssh_client
        is_alias = None
        try:
            is_alias = self.store.get(alias)
        except Exception as e:
            logger.debug("Exception while getting alias {}".format(e))
            pass
        if is_alias is None:
            self.store.add(host_details, alias)
        ssh_shell = self._invoke_shell(alias)
        host_details["shell_object"] = ssh_shell

    def execute_command(self, command, alias, return_rc=False, pty=False):
        """
        Executes command on ssh session with reference to given alias
        @param command: string, command to execute
        @param alias: string, Execution context
        @param pty: (Boolean) : True or False
        @param return_rc: bool, returns error output
        @return: response received from ssh session read-lines
        @raise SSHException: raises an exception
        """
        ssh_session = self.store.get(alias)['session_object']
        stdin, stdout, stderr = ssh_session.exec_command(command, get_pty=pty)
        time.sleep(1)
        out_val = stdout.read()
        err_val = stderr.read()
        if err_val:
            error = [True for error in self.root_error_list if error.lower() in decode_str(err_val).lower()]
            if error:
                stdin, stdout, stderr = ssh_session.exec_command('sudo {}'.format(command))
                time.sleep(1)
                out_val = stdout.read()
                err_val = stderr.read()
        if stderr.readlines() == 1:
            logger.warn("Failed to execute command {} got error {}".format(command, stderr))
        logger.debug("out value from execute_command {} ".format(decode_str(out_val).strip()))
        if return_rc:
            return decode_str(out_val), decode_str(err_val)
        return decode_str(out_val).strip()

    def execute_command_on_shell(self, command, alias, exit_prompt=None, timeout=5, return_rc=False):
        """
        Executes command on ssh shell with reference to given alias
        @param command: string, command to execute
        @param alias: string, Execution context
        @param exit_prompt: string, expected prompt after executing given command
        @param return_rc: bool, return err if True
        @param timeout: int, timeout. Default 5
        @return: response received from the channel
        @raise 	SSHException: raises an exception
        """
        errdata = []
        err = ''
        time.sleep(2)
        ssh_shell = self._invoke_shell(alias)
        ssh_shell.send(command + '\n')
        time.sleep(2)
        output = ssh_shell.recv(65535)
        error = [True for error in self.root_error_list if error.lower() in decode_str(output).lower()]
        if error:
            ssh_shell.send("sudo {}\n".format(command))
            time.sleep(2)
            output = ssh_shell.recv(65535)
        while True:  # monitoring process
            # Reading from output streams
            while ssh_shell.recv_ready():
                output = ssh_shell.recv(65535)
            while ssh_shell.recv_stderr_ready():
                errdata += ssh_shell.recv_stderr(65535)
            if ssh_shell.exit_status_ready():  # If completed
                logger.debug("Shell execution completed !!")
                break
            if timeout == 0 and not exit_prompt:
                break
            if exit_prompt and exit_prompt in decode_str(output):
                break
            timeout = timeout - 1
            time.sleep(1)
        time.sleep(1)
        if errdata:
            logger.warn("error value received {} while executing {}".format(errdata, command))
        if return_rc:
            return decode_str(output), decode_str(err.join(errdata))
        return decode_str(output)

    def connect_to_hop(self, command, alias, password=None, prompt='$'):
        """
        Connect to hop
        @param command: string, command to execute
        @param alias: string, Execution context
        @param password: string, password. Default None if password is not required
        @param prompt: string, send expected prompt. default '$'
        @raise 	SSHException, Exception: raises an exception
        """
        ssh_shell = self._invoke_shell(alias)
        # ssh_shell.send(cmd+'\n')
        ssh_shell.send('{}'.format(command) + '\n')
        for i in range(2):
            output = decode_str(ssh_shell.recv(65535))
            time.sleep(1)
            if "Are you sure you want to continue connecting" in output:
                ssh_shell.send('yes' + '\n')
                time.sleep(1)
                output = decode_str(ssh_shell.recv(65535))
            if password is not None and bool(re.search(".*password:",
                                                       output,
                                                       re.MULTILINE | re.DOTALL | re.IGNORECASE)):
                ssh_shell.send(password + '\n')
                time.sleep(1)
                output = decode_str(ssh_shell.recv(65535))
                break
            elif prompt in output:
                break
            time.sleep(1)
        else:
            raise Exception("Error during remote login to {}".format(output))

        for j in range(2):
            if command in output:
                logger.debug("SSH connection to remote shell is successful !!")
                break
            elif "Last login:" in output:
                logger.debug("SSH connection to remote shell is successful !!")
                break
            elif prompt in output:
                break
            time.sleep(1)
            output = decode_str(ssh_shell.recv(65535))
        else:
            raise SSHException(
                "SSH connection remote shell was not successful !!{}".format(output))
        return output

    def exit_from_hop_connection(self, alias):
        """
        This method exits from the SSH connection specified by alias. This is most used to exit
        multiple/double ssh connections by specifying its alias created during setup method
        @param alias: string, Execution context.
        @return:
        @raise SSHException: raises an exception
        """
        try:
            ssh_shell = self._invoke_shell(alias)
            ssh_shell.send('exit' + '\n')
        except Exception as e:
            raise Exception("Error during exit hop connection : {}".format(e))

    def close_ssh_session_with_host(self, alias):
        """
        Closes an open connection with reference to given alias
        @param alias: string, Execution context
        @raise 	KeyError: raises an exception
        """
        try:
            self.store.get(alias)["session_object"].close()
        except Exception as e:
            raise Exception("Error while closing ssh session {}".format(e))
        finally:
            self.store.remove(alias=alias)

    def get_file_from_host(self, source, dest, alias):
        """
        Executes command on ssh session with reference to given alias
        @param source: Path on the remote machine
        @param dest: Path on the local machine
        @param alias: string, Execution context
        @return: a list with [(source,destination)]
        @raise SSHException: raises an exception
        """
        scp_client = SCPClient(self.store.get(alias)['session_object'].get_transport())
        try:
            scp_client.get(source, dest)
            return dest
        except SCPClient as e:
            logger.error("Failed while getting file from {} to {} :: {}".format(source, dest, e))
        except Exception as e:
            logger.error("Exception {}".format(e))
        finally:
            scp_client.close()

    def put_file_on_host(self, source, destination, alias):
        scp_client = SCPClient(self.store.get(alias)['session_object'].get_transport())
        try:
            scp_client.put(source, destination)
            return source
        except SCPClient as e:
            logger.error("Failed while getting file from {} to {} with error {}".format(source, destination, e))
        finally:
            scp_client.close()

    @staticmethod
    def keygen_write_to_file(filename, passwd=None, bits=2048):
        if os.path.isfile(filename):
            with open(filename + '.pub', 'r') as pub_file:
                public_key = pub_file.read()
            logger.info("public key:", public_key.rstrip())
            return public_key.rstrip()
        key_obj = SshController._generate_keys()
        key_obj.write_private_key_file(filename, password=passwd)
        file_permissions_o600 = 384
        with open(filename + '.pub', 'w', file_permissions_o600) as pub_file:
            os.chmod(filename + '.pub', file_permissions_o600)
            current_user = getpass.getuser()
            public_key = 'ssh-rsa ' + key_obj.get_base64() + ' ' + current_user
            pub_file.write(public_key)
        return public_key

    @staticmethod
    def upload_keys_to_remote_host(host_details, public_key, root_user_public_key=None,
                                   user_param_path=None,
                                   root_user_param_path=None, upload_keys_mode='admin',
                                   **kwargs
                                   ):
        logger.info("Copying keys to remote host ...\n")

        admin_obj = Commissioning()
        if upload_keys_mode == 'admin':
            try:
                alias = SshController._check_for_admin_setup(admin_obj)
                if host_details.get('user_param_path'):
                    admin_obj.perform_recommissioning(type='param', rat='lte',
                                                      param_path=host_details['user_param_path'],
                                                      operation='update',
                                                      value=[{'keyValue': public_key}], alias=alias)
                if host_details.get('root_user_param_path'):
                    admin_obj.perform_recommissioning(type='param', rat='lte',
                                                      param_path=host_details[
                                                          'root_user_param_path'],
                                                      operation='update',
                                                      value=[{'keyValue': root_user_public_key}],
                                                      alias=alias)
            except Exception as key_copy_exception:
                raise Exception(
                    "Copying ssh keys to remote host failed ...{}".format(key_copy_exception))

    @staticmethod
    def _generate_keys(bits=2048):
        return RSAKey.generate(bits)

    @staticmethod
    def _check_for_admin_setup(admin_obj):
        if not global_vars.setup_admin_called:
            logger.info("Setting up admin to copy keys as there are no existing admin sessions...")
            admin_alias = "alias_ssh_key_handler"
            admin_obj.setup_oamops(alias=admin_alias, execute_through_interface=False)
        else:
            admin_alias = global_vars.admin_alias
            logger.debug("Using admin alias: {}".format(admin_alias))
        return admin_alias

    def _connect(self, ssh_client, alias, host_details):
        if not self.store.has_alias(alias) or self.store.get(alias) is None:
            logger.debug(
                "ssh session for alias {} doesn't exist. Creating a connection".format(alias))
            try:
                logger.debug("IS remote host given {}".format(host_details['remote_host']))
                if host_details['remote_host']:
                    logger.debug("Logging to remote host")
                    self.remote_connection(ssh_client=ssh_client, host_details=host_details)
                else:
                    logger.debug("Logging to local host")
                    self.local_connection(ssh_client=ssh_client, host_details=host_details)

            except Exception as e:
                raise SSHException("{} thrown. Make sure provided ssh ip {} is pingable".format(
                    e, host_details['ip']))
            return ssh_client
        else:
            logger.debug(
                "ssh session for alias {} already exist. Returning session object".format(
                    alias))
        return self.store.get(alias)["session_object"]

    def remote_connection(self, ssh_client, host_details):
        ssh_client.connect(hostname=host_details['remote_host'],
                           username=host_details['remote_ssh_user'],
                           password=host_details['remote_ssh_pass'])

    def local_connection(self, ssh_client, host_details):
        if host_details.get('private_key'):
            ssh_client.connect(hostname=host_details['ip'],
                               username=host_details['user'],
                               password=host_details['password'], port=str(host_details['port']),
                               key_filename=host_details['private_key'])
        elif host_details.get('port'):
            ssh_client.connect(hostname=host_details['ip'], port=str(host_details['port']),
                               username=host_details['user'],
                               password=host_details['password'])
        else:
            ssh_client.connect(hostname=host_details['ip'], username=host_details['user'],
                               password=host_details['password'])


    def _invoke_shell(self, alias):
        ssh_session = self.store.get(alias)["session_object"]
        if "shell_object" not in self.store.get(alias) or self.store.get(alias)["shell_object"] \
                is None:
            ssh_shell = ssh_session.invoke_shell()
            return ssh_shell
        return self.store.get(alias)["shell_object"]

    def _close_ssh_session_with_host(self, store, alias, ssh_session):
        try:
            ssh_session.close()
        except Exception as e:
            raise Exception("Error while closing ssh session {}".format(e))
        finally:
            store.remove(alias=alias)
